use vstd::prelude::*;

verus! {

fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> (res: Vec<char>)
    ensures
        // Let len = length of original, w = target width
        let len = orig.len();
        let w = width as usize;
        // Result length is max(len, w)
        res.len() == if len >= w { len } else { w } &&
        // If original is already at least as wide, result equals original
        (if len >= w {
            res == orig
        } else {
            // Otherwise, the first w-len chars are fillchar
            // and the last len chars equal orig
            forall |i: usize| i < w - len ==> res[i] == fillchar &&
            forall |j: usize| j < len     ==> res[(w - len) + j] == orig[j]
        })
{
    let len: usize = orig.len();
    let w: usize = width as usize;
    // If no padding needed, just return the original
    if len >= w {
        return orig;
    }
    // Otherwise, build a new vector of length w
    let pad: usize = w - len;
    let mut res: Vec<char> = Vec::new();
    res.reserve(w);

    // Push fillchar pad times
    let mut i: usize = 0;
    while i < pad
        invariant
            i <= pad,
            res.len() == i,
        decreases pad - i,
    {
        res.push(fillchar);
        i = i + 1;
    }

    // Append the original characters
    let mut j: usize = 0;
    while j < len
        invariant
            j <= len,
            res.len() == pad + j,
        decreases len - j,
    {
        // orig is indexed in specification and at runtime
        res.push(orig[j]);
        j = j + 1;
    }

    res
}

} // verus!

